using System;using System.Reflection;using System.Collections;using System.IO;using System.Linq;using UnityEditor;using UnityEngine.TestTools;using NUnit.Framework;using LighFight.Core;using LighFight.Runtime;using UnityEngine;
namespace LighFight.Tests {
public sealed class EmbeddedContentTests {
 static Type Descriptor(){var t=typeof(ContentManifest).Assembly.GetType("LighFight.Core.EmbeddedContentDescriptor");Assert.NotNull(t,"Embedded descriptor implementation required");return t;}
 static object Valid(){var t=Descriptor();var d=Activator.CreateInstance(t);foreach(var p in new[]{new[]{"contentVersion","review-1"},new[]{"platform","StandaloneOSX"},new[]{"unityVersion","6000.3.26f1"}})t.GetField(p[0]).SetValue(d,p[1]);return d;}
 static string Validate(object d)=> (string)d.GetType().GetMethod("Validate").Invoke(d,new object[]{"StandaloneOSX","6000.3.26f1"});
 [Test]public void CurrentPackagedDescriptorIsAccepted(){Assert.IsNull(Validate(Valid()));}
 [TestCase("minimumPlayerVersion",3,"incompatible_player")][TestCase("minimumPlayerVersion",0,"incompatible_player")][TestCase("schemaVersion",2,"incompatible_player")]
 public void UnsupportedPlayerOrSchemaFails(string field,int value,string expected){var d=Valid();d.GetType().GetField(field).SetValue(d,value);Assert.AreEqual(expected,Validate(d));}
 [TestCase("platform","iOS","incompatible_platform")][TestCase("unityVersion","6000.3.25f1","incompatible_platform")][TestCase("contentVersion","../escape","invalid_version")][TestCase("contentVersion","","invalid_version")][TestCase("starterLabel","all-fighters","invalid_content")][TestCase("assetAddress","other","invalid_content")]
 public void IncompatibleOrInvalidMetadataFails(string field,string value,string expected){var d=Valid();d.GetType().GetField(field).SetValue(d,value);Assert.AreEqual(expected,Validate(d));}
 [TestCase(-1L)][TestCase(1L)]public void EmbeddedDescriptorCannotRequestDownload(long bytes){var d=Valid();d.GetType().GetField("downloadBytes").SetValue(d,bytes);Assert.AreEqual("invalid_size",Validate(d));}
 [Test]public void EmbeddedDescriptorHasNoBodyReferences(){foreach(var f in Descriptor().GetFields())Assert.IsFalse(typeof(UnityEngine.Object).IsAssignableFrom(f.FieldType),f.Name);}
 [Test]public void ExplicitEmbeddedBootstrapDoesNotRequireManifestUrl(){Assert.NotNull(typeof(ContentBootstrap).GetField("useEmbeddedCatalog"));Assert.NotNull(typeof(ContentBootstrap).GetField("embeddedDescriptor"));}
 [Test]public void EmbeddedIosExportRejectsDesktopBeforeWritingBuild(){
  if(EditorUserBuildSettings.activeBuildTarget==BuildTarget.iOS)Assert.Ignore("Desktop platform guard requires a desktop editor target");
  var t=Type.GetType("LighFight.Editor.Setup, Assembly-CSharp-Editor");var method=t.GetMethod("ExportEmbeddedIos");Assert.NotNull(method,"Embedded phone delivery needs an explicit local-catalog export path");
  string path=Path.Combine(Path.GetTempPath(),"lighfight-ios-export-guard-"+Guid.NewGuid().ToString("N"));string old=Environment.GetEnvironmentVariable("LIGHFIGHT_EMBEDDED_IOS_EXPORT");
  try{Environment.SetEnvironmentVariable("LIGHFIGHT_EMBEDDED_IOS_EXPORT",path);var error=Assert.Throws<TargetInvocationException>(()=>method.Invoke(null,null));Assert.IsInstanceOf<InvalidOperationException>(error.InnerException);StringAssert.Contains("buildTarget iOS",error.InnerException.Message);Assert.IsFalse(Directory.Exists(path),"Wrong-platform export must not write a player or content build");}finally{Environment.SetEnvironmentVariable("LIGHFIGHT_EMBEDDED_IOS_EXPORT",old);}
 }
 [Test]public void EmbeddedPackagingEntryPointExists(){var t=Type.GetType("LighFight.Editor.ContentBuild, Assembly-CSharp-Editor");Assert.NotNull(t);Assert.NotNull(t.GetMethod("BuildEmbedded"));}
 [Test]public void RemoteTransportAndVersionRemainCompatible(){var m=new ContentManifest{contentVersion="v1",platform="StandaloneOSX",unityVersion="6000.3.26f1",catalogUrl="file:///tmp/catalog.json"};Assert.AreEqual("invalid_catalog",m.Validate("StandaloneOSX","6000.3.26f1",true));m.catalogUrl="https://example.test/catalog.json";Assert.IsNull(m.Validate("StandaloneOSX","6000.3.26f1"));Assert.AreEqual(2,ContentManifest.CurrentPlayerVersion);}

 static object Get(object o,string name){var t=o.GetType();return t.GetProperty(name)?.GetValue(o)??t.GetField(name)?.GetValue(o);}
 static void Drain(IEnumerator e){int steps=0;while(e.MoveNext()){Assert.Less(++steps,10);if(e.Current is IEnumerator nested)Drain(nested);else Assert.Fail("Unexpected async resource/network operation before configuration validation");}}
 [TestCase(true,"embedded_not_configured")][TestCase(false,"delivery_not_configured")]
 public void InvalidStartupFailsBeforeResourceIoAndPreservesRemoteCache(bool embeddedMode,string code){
  var obj=new GameObject("Bootstrap invalid startup test");try{var b=obj.AddComponent<ContentBootstrap>();var field=typeof(ContentBootstrap).GetField("useEmbeddedCatalog");Assert.NotNull(field);field.SetValue(b,embeddedMode);var path=Path.Combine(Application.persistentDataPath,"lighfight-manifest.json");var before=File.Exists(path)?File.ReadAllBytes(path):null;LogAssert.Expect(LogType.Warning,"LighFight content: "+code);Drain((IEnumerator)typeof(ContentBootstrap).GetMethod("Check",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(b,null));Assert.AreEqual(code,b.ErrorCode);Assert.IsFalse(b.IsPlaying);CollectionAssert.AreEqual(before,File.Exists(path)?File.ReadAllBytes(path):null);}finally{UnityEngine.Object.DestroyImmediate(obj);}
 }
 [Test]public void EmbeddedPlatformIsExplicitAndLegacyRemotePlatformRemainsUnchanged(){Assert.NotNull(typeof(ContentBootstrap).GetProperty("EmbeddedPlatformName"));Assert.AreEqual("StandaloneOSX",ContentBootstrap.PlatformName);}
 [Test]public void EmbeddedRejectsInlineCatalogWhileRemoteAcceptsIt(){var method=typeof(ContentBootstrap).GetMethod("ValidateOpenedContent",BindingFlags.Instance|BindingFlags.NonPublic);Assert.NotNull(method,"Embedded startup must reject inline body roots");var obj=new GameObject("Inline metadata test");var c=ScriptableObject.CreateInstance<GameContent>();try{c.fighters=new[]{AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Content/fighter-1.prefab")};c.arenas=new[]{AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Content/arena-0.prefab")};var b=obj.AddComponent<ContentBootstrap>();b.useEmbeddedCatalog=true;Assert.AreEqual("embedded_inline_content",method.Invoke(b,new object[]{c}));b.useEmbeddedCatalog=false;Assert.IsNull(method.Invoke(b,new object[]{c}));}finally{UnityEngine.Object.DestroyImmediate(c);UnityEngine.Object.DestroyImmediate(obj);}}
 [Test]public void OwnedGroupsAreLocalUnrelatedEntriesSurviveAndMetadataHasNoBodies(){
  var builder=Type.GetType("LighFight.Editor.ContentBuild, Assembly-CSharp-Editor");var method=builder.GetMethod("ConfigureEmbeddedContent");Assert.NotNull(method,"Local ownership-preserving packaging required");
  const string folder="Assets/EmbeddedTestFixtures";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var st=Type.GetType("UnityEditor.AddressableAssets.Settings.AddressableAssetSettings, Unity.Addressables.Editor");Assert.NotNull(st);var settings=st.GetMethod("Create",BindingFlags.Public|BindingFlags.Static).Invoke(null,new object[]{folder+"/AA","Settings",true,true});var source=ScriptableObject.CreateInstance<GameContent>();
  try{
   source.fighters=new[]{AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Content/fighter-1.prefab"),AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Content/fighter-6.prefab")};source.arenas=new[]{AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Content/arena-0.prefab")};Assert.IsTrue(source.ValidateCatalog(out var validation),validation);AssetDatabase.CreateAsset(source,folder+"/Source.asset");
   var foreign=st.GetMethod("CreateGroup").Invoke(settings,new object[]{"Unrelated tool",false,false,false,null,new Type[0]});File.WriteAllText(folder+"/foreign.txt","preserve me");AssetDatabase.Refresh();var entry=st.GetMethod("CreateOrMoveEntry").Invoke(settings,new object[]{AssetDatabase.AssetPathToGUID(folder+"/foreign.txt"),foreign,false,true});entry.GetType().GetProperty("address").SetValue(entry,"external/notes");
   var output=folder+"/Embedded.asset";var catalog=(GameContent)method.Invoke(null,new object[]{source,settings,output});Assert.IsTrue(catalog.streamed);Assert.AreEqual(0,catalog.fighters.Length);Assert.AreEqual(0,catalog.arenas.Length);Assert.AreEqual(2,catalog.fighterAddresses.Length);Assert.AreEqual("external/notes",Get(entry,"address"));Assert.AreSame(foreign,Get(entry,"parentGroup"));Assert.AreEqual(false,Get(settings,"BuildRemoteCatalog"));
   var profile=Get(settings,"profileSettings");foreach(var name in new[]{"LighFight Embedded Fighters","LighFight Embedded Arenas","LighFight Embedded Shared Motions","LighFight Embedded Starter"}){
    var group=st.GetMethod("FindGroup",new[]{typeof(string)}).Invoke(settings,new object[]{name});Assert.NotNull(group,name);var schemaType=Type.GetType("UnityEditor.AddressableAssets.Settings.GroupSchemas.BundledAssetGroupSchema, Unity.Addressables.Editor");var schema=group.GetType().GetMethod("GetSchema",new[]{typeof(Type)}).Invoke(group,new object[]{schemaType});foreach(var pair in new[]{new[]{"BuildPath","Local.BuildPath"},new[]{"LoadPath","Local.LoadPath"}}){var reference=Get(schema,pair[0]);var expected=profile.GetType().GetMethod("GetVariableId",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(profile,new object[]{pair[1]});Assert.AreEqual(expected,Get(reference,"Id"));}}
   var deps=AssetDatabase.GetDependencies(output,true);Assert.IsFalse(deps.Any(x=>x.EndsWith(".prefab")),"Starter metadata must not depend on bodies/arena");
  }finally{AssetDatabase.DeleteAsset(folder);if(source)UnityEngine.Object.DestroyImmediate(source);}
 }
}}
